Caveman mode: **full**.

---

```tsx
// ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

// ── Types ────────────────────────────────────────────────────────────────────

interface Props {
  children: ReactNode;
  fallback?: (error: Error, retry: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

// ── Logger ───────────────────────────────────────────────────────────────────

function logError(error: Error, info: ErrorInfo): void {
  console.group("[ErrorBoundary]");
  console.error("Error     :", error.message);
  console.error("Stack     :", error.stack);
  console.error("Component :", info.componentStack);
  console.groupEnd();

  // Swap for real service: Sentry.captureException(error, { extra: info })
}

// ── Default fallback UI ──────────────────────────────────────────────────────

function DefaultFallback({
  error,
  retry,
}: {
  error: Error;
  retry: () => void;
}) {
  return (
    <div role="alert" style={styles.wrapper}>
      <span style={styles.icon}>⚠️</span>
      <h2 style={styles.heading}>Something went wrong</h2>
      <pre style={styles.message}>{error.message}</pre>
      <button onClick={retry} style={styles.button}>
        Retry
      </button>
    </div>
  );
}

// ── Error Boundary ───────────────────────────────────────────────────────────

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, errorInfo: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };                        // triggers fallback render
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    this.setState({ errorInfo: info });
    logError(error, info);
    this.props.onError?.(error, info);       // caller hook (Sentry, etc.)
  }

  retry = (): void => {
    this.setState({ error: null, errorInfo: null });
  };

  render(): ReactNode {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    return fallback
      ? fallback(error, this.retry)          // custom fallback
      : <DefaultFallback error={error} retry={this.retry} />;
  }
}

// ── Inline styles ────────────────────────────────────────────────────────────

const styles: Record<string, React.CSSProperties> = {
  wrapper: {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    gap: "12px",
    padding: "40px 24px",
    fontFamily: "sans-serif",
    color: "#333",
  },
  icon:    { fontSize: "48px" },
  heading: { margin: 0, fontSize: "20px" },
  message: {
    background: "#f5f5f5",
    padding: "12px 16px",
    borderRadius: "6px",
    fontSize: "13px",
    maxWidth: "480px",
    overflowX: "auto",
  },
  button: {
    padding: "8px 20px",
    background: "#0070f3",
    color: "#fff",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer",
    fontSize: "14px",
  },
};
```

```tsx
// Usage — basic
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// Usage — custom fallback
<ErrorBoundary
  fallback={(error, retry) => (
    <MyFancyFallback message={error.message} onRetry={retry} />
  )}
  onError={(error, info) => Sentry.captureException(error, { extra: info })}
>
  <MyComponent />
</ErrorBoundary>
```

---

**Key decisions:**

| Choice | Why |
|---|---|
| Class component | Hooks no support `componentDidCatch` yet |
| `getDerivedStateFromError` | Static — runs before re-render, sets error state fast |
| Separate `componentDidCatch` | Instance method — needed for side effects (logging) |
| `retry` reset both `error` + `errorInfo` | Stale `errorInfo` after retry cause confusion |
| `fallback` as render-prop | Caller control UI without forking component |

**Limits:** Boundary no catch: async errors, event handlers, errors in boundary itself. For those — use `window.onerror` or try/catch at call site.
